import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.SLwxmuMO.js";var i=JSON.parse(`{"title":"recon","description":"","frontmatter":{},"headers":[],"relativePath":"CHANGELOG.md","filePath":"CHANGELOG.md"}`),a={name:`CHANGELOG.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="recon" tabindex="-1">recon <a class="header-anchor" href="#recon" aria-label="Permalink to “recon”">​</a></h1><h2 id="_0-1-5" tabindex="-1">0.1.5 <a class="header-anchor" href="#_0-1-5" aria-label="Permalink to “0.1.5”">​</a></h2><h3 id="patch-changes" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li><a href="https://github.com/markmals/recon/pull/88" target="_blank" rel="noreferrer">#88</a> <a href="https://github.com/markmals/recon/commit/db9cc2f5bbb2a456fc66520cc3424edd215cb03b" target="_blank" rel="noreferrer"><code>db9cc2f</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - <code>recon ui session prepare-host</code> no longer fails with <code>UI_INTERFERENCE</code> when <code>sudo</code> asks for your password or Touch ID. Host preparation inspects no application, so it no longer runs under the watch that keeps <code>ui</code> commands from stealing focus, and <code>recon schema ui session prepare-host</code> no longer lists <code>UI_INTERFERENCE</code> or <code>INTERFACE_UNAVAILABLE</code>. Before this release the command reported that error after it had already applied its changes; <code>recon ui session prepare-host --status</code> shows what was applied. A <code>ui</code> command that fails because a privacy permission is missing now always reports <code>PERMISSION_DENIED</code>, even if macOS&#39;s request dialog came forward while it ran.</li></ul><h2 id="_0-1-4" tabindex="-1">0.1.4 <a class="header-anchor" href="#_0-1-4" aria-label="Permalink to “0.1.4”">​</a></h2><h3 id="patch-changes-1" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-1" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li><a href="https://github.com/markmals/recon/pull/86" target="_blank" rel="noreferrer">#86</a> <a href="https://github.com/markmals/recon/commit/5c556e88b41ac064d4ef4b3cc0b7254fcadfb12a" target="_blank" rel="noreferrer"><code>5c556e8</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - <code>recon ui</code> commands no longer fail with <code>UI_INTERFERENCE</code> (&quot;keyboard, button or scroll events were posted into the session that the hardware did not generate&quot;) because you typed while they ran. macOS sometimes counts a real keystroke a moment later in the session than in the hardware, and Recon read that delay as input something else had posted. This most often hit <code>recon ui session prepare-host</code>, whose confirmation you type while it runs; when it happened, the preparation had already been applied. Input that the hardware never generated is still reported.</li></ul><h2 id="_0-1-3" tabindex="-1">0.1.3 <a class="header-anchor" href="#_0-1-3" aria-label="Permalink to “0.1.3”">​</a></h2><h3 id="patch-changes-2" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-2" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li><p><a href="https://github.com/markmals/recon/pull/83" target="_blank" rel="noreferrer">#83</a> <a href="https://github.com/markmals/recon/commit/bce2b56d91b384905102d11382dbafde069b97ac" target="_blank" rel="noreferrer"><code>bce2b56</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - <code>recon ui session open --profile research</code> no longer fails with <code>INSPECTION_UNAVAILABLE</code> &quot;could not acquire the task control port (kern_return 5)&quot; for targets such as TextEdit and Calculator. Recon now reads the selected process&#39;s identity without needing debugger rights, and only the entitled <code>recon-loader</code> takes control of the target, so the Homebrew-installed <code>recon</code> works without being re-signed.</p></li><li><p><a href="https://github.com/markmals/recon/pull/82" target="_blank" rel="noreferrer">#82</a> <a href="https://github.com/markmals/recon/commit/da2074dd77cbfba89a4c65b0aa545247b9ae6b73" target="_blank" rel="noreferrer"><code>da2074d</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - Native inspection&#39;s in-process helper is now built from Swift, and <code>recon ui view</code> answers with the same observations as before. One difference is a correction: <code>coverage.complete</code> is now reported as <code>true</code> or <code>false</code>, as the published schema always said, where the previous helper reported <code>1</code> or <code>0</code>. Building Recon from source, including Homebrew&#39;s source build, now requires Apple&#39;s Swift 6.4 compiler build <code>swiftlang-6.4.0.34.1</code>, from Xcode 27.1 or the Command Line Tools; installing the bottle needs nothing new.</p></li><li><p><a href="https://github.com/markmals/recon/pull/83" target="_blank" rel="noreferrer">#83</a> <a href="https://github.com/markmals/recon/commit/2ba8cafd61fbfacb9236995ea13346e1752613f5" target="_blank" rel="noreferrer"><code>2ba8caf</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - <code>recon ui session open --profile research</code> now works for App Sandboxed applications such as TextEdit and Calculator. Previously the helper loaded but never answered, the open timed out with <code>INSPECTION_TIMEOUT</code>, and every retry returned <code>INSPECTION_BUSY</code> until the application quit. The sandbox still has to be able to read the helper. When it cannot, as with Homebrew&#39;s install directory, Recon now refuses with <code>INSPECTION_UNAVAILABLE</code> before loading anything, naming the helper path.</p></li><li><p><a href="https://github.com/markmals/recon/pull/83" target="_blank" rel="noreferrer">#83</a> <a href="https://github.com/markmals/recon/commit/79d9ed12107fb54ead1eac752e114f8ef0b6712a" target="_blank" rel="noreferrer"><code>79d9ed1</code></a> Thanks <a href="https://github.com/markmals" target="_blank" rel="noreferrer">@markmals</a>! - <code>recon ui session prepare-host</code> now also creates <code>/Library/Application Support/Recon</code> through <code>sudo</code>, owned by you, and copies Recon&#39;s research helper into it. App Sandboxed applications such as TextEdit and Calculator can read that location. Run it again after upgrading Recon: research sessions use the copied helper only while it is identical to the packaged one, and otherwise use the packaged helper. <code>--status</code> reports the copy as <code>stagedHelper</code>. <code>--revert</code> removes it, and the directory if nothing else is in it; removing only the helper reports <code>rebootRequired: false</code>. Applied and reverted results carry a new <code>stagedHelper</code> member naming the helper copied or removed.</p></li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};